def compact(value, n=500):
    return str(value or '').strip()[:n]

def obj_schema(properties, required=None):
    return {'type':'OBJECT','properties':properties,'required':required or list(properties)}

T = {'type':'STRING'}
ALLOWED_DIMENSIONS={'conceptual','recognition','variables','units','equation_manipulation','method_selection','direct_application','contextual_application','interpretation','transfer','procedure','memory','self_explanation'}
TARGETED_ACTIVITY_FAMILIES={
    'variables':'variable_identification',
    'units':'units',
    'equation_manipulation':'equation_manipulation',
    'method_selection':'method_selection',
}
REVIEW_ACTIVITY_FAMILIES={**TARGETED_ACTIVITY_FAMILIES,'memory':'recall'}
CONFIRMATION_KINDS={**TARGETED_ACTIVITY_FAMILIES,'conceptual':'explanation','recognition':'recognition','direct_application':'application','contextual_application':'context_case','interpretation':'interpretation','procedure':'procedure','memory':'recall','self_explanation':'self_explanation'}
DIMENSION_LIST={'type':'ARRAY','items':T}
Q = obj_schema({'prompt':T,'reference':T,'kind':T,'observable_dimensions':DIMENSION_LIST},
               ['prompt','reference','kind'])
# Repair plans use a stricter provider contract than legacy micro-lessons:
# every diagnostic or teaching activity must carry its observable dimensions
# in the model response.  Local validation remains authoritative.
