# performs the authoritative role/family intersection below.
REPAIR_DIAGNOSTIC_KINDS=sorted(set(TARGETED_ACTIVITY_FAMILIES.values())|{'application','calculation','explanation','problem','procedure','recognition'})
REPAIR_APPLICATION_KINDS=['application','calculation','problem','procedure']
REPAIR_CHECK_KINDS=['explanation','recognition']
REPAIR_TRANSFER_KINDS=['transfer']
def repair_question_schema(kinds,dimensions):
    return obj_schema({'prompt':T,'reference':T,'kind':{'type':'STRING','enum':list(kinds)},'observable_dimensions':{'type':'ARRAY','items':{'type':'STRING','enum':sorted(dimensions)}}})
REPAIR_DIAGNOSTIC_Q=repair_question_schema(REPAIR_DIAGNOSTIC_KINDS,{'conceptual','recognition','variables','units','equation_manipulation','method_selection','direct_application','procedure'})
REPAIR_CHECK_Q=repair_question_schema(REPAIR_CHECK_KINDS,{'conceptual','recognition'})
REPAIR_APPLICATION_Q=repair_question_schema(REPAIR_APPLICATION_KINDS,{'direct_application','procedure'})
REPAIR_TRANSFER_Q=repair_question_schema(REPAIR_TRANSFER_KINDS,{'contextual_application','interpretation','transfer'})
REPAIR_Q=REPAIR_DIAGNOSTIC_Q
NODE = obj_schema({'id':T,'name':T,'outcome':T,'level':{'type':'INTEGER'},
                   'prerequisites':{'type':'ARRAY','items':T},'kind':T,
                   'probe':Q})
