def review_question(data):
    goal=compact(data.get('goal'),160);concept=compact(data.get('concept'),90)
    if not goal or not concept:raise ValueError('Falta meta o concepto.')
    target_dimension=compact(data.get('target_dimension'),40)
    if target_dimension and target_dimension not in REVIEW_ACTIVITY_FAMILIES:raise ValueError('La dimensión objetivo del repaso no es compatible.')
    target_instruction=''
    if target_dimension:
        target_kind=REVIEW_ACTIVITY_FAMILIES[target_dimension]
        target_instruction=(f' La dimensión objetivo es {target_dimension}. Usa kind exacto {target_kind} y '
          f'observable_dimensions exactamente ["{target_dimension}"], sin dimensiones adicionales. No la atribuyas a otra capacidad.')
    raw=gemini(f'Objetivo: {goal}; concepto: {concept}; nivel de repaso: {compact(data.get("level"),5)}. '
      'Crea UNA pregunta nueva de recuperación que aplique el mismo concepto a otro contexto. Declara kind y observable_dimensions limitadas a lo que la pregunta observa.'+target_instruction+
      ' No repitas: '+compact(data.get('previous'),300)+'. Respuesta de referencia breve.',REVIEW_SCHEMA,550)
    q=raw.get('question',{}) if isinstance(raw,dict) else {}
    try:q=clean_question(q,700,700)
    except ValueError:raise ValueError('Pregunta de repaso incompleta.')
    if target_dimension:
        expected_kind=REVIEW_ACTIVITY_FAMILIES[target_dimension]
        if q.get('_invalid_observable_dimensions') or q.get('kind')!=expected_kind or q.get('observable_dimensions')!=[target_dimension]:
            raise ValueError(f'La actividad de repaso para {target_dimension} debe usar kind {expected_kind} y observar únicamente {target_dimension}.')
    return {'question':q,'target_dimension':target_dimension or None,'temporal_policy_version':TEMPORAL_POLICY_VERSION}

MICRO_SCHEMA=obj_schema({'focus':T,'explanation':T,'representation':T,
 'steps':{'type':'ARRAY','items':Q},'transfer':Q})
